const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let x = Number(input[0]);
const n = BigInt(input[1]);
const MOD = 1000000007n;

const primes = [];

if (x % 2 === 0) {
    primes.push(2);
    while (x % 2 === 0) x /= 2;
}

for (let p = 3; p * p <= x; p += 2) {
    if (x % p === 0) {
        primes.push(p);
        while (x % p === 0) x /= p;
    }
}

if (x > 1) primes.push(x);

function modPow(base, exponent) {
    let result = 1n;
    base %= MOD;

    while (exponent > 0n) {
        if (exponent & 1n) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1n;
    }

    return result;
}

let answer = 1n;

for (const prime of primes) {
    const p = BigInt(prime);
    let power = p;
    let exponent = 0n;

    while (power <= n) {
        exponent += n / power;
        power *= p;
    }

    answer = answer * modPow(p, exponent) % MOD;
}

console.log(answer.toString());

